llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "Lefamulin absolute oral bioavailability was 25.8% in fasted healthy adults after a 600 mg immediate-release tablet compared with IV, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C50"],
      "claim": "Zidovudine mean absolute oral bioavailability was 64.0 ± 18.8% in 16 patients after 200 mg oral administration compared with IV, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "In normal subjects, tacrolimus absolute oral bioavailability was 17.8% after a 5 mg oral dose compared with IV, below the 20% threshold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Multiple high-transfer absolute bioavailability records exceed 20% (25.8%, 64%, 100%), supporting high; one strong ordinary-condition absolute record is 17.8% and one evidence group has a provenance conflict, so confidence is moderate.",
  "evidence_gaps": [
    "Molecule 2 records appear to refer to different compounds (amphotericin B, Uniphyl, voriconazole, posaconazole); discounted as provenance conflict.",
    "Molecule 1 has conflicting absolute bioavailability records around the 20% threshold; the strongest ordinary-condition record is below 20% while other absolute records are 20–25%."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

